import { QueryFlag, Utils, raw } from '@mikro-orm/core';
import { QueryBuilder } from '@mikro-orm/sql';
/** Query builder with MSSQL-specific behavior such as identity insert handling. */
export class MsSqlQueryBuilder extends QueryBuilder {
    insert(data) {
        data = this.applyInsertDefaults(data);
        this.checkIdentityInsert(data);
        if (this.mainAlias.meta?.hasTriggers) {
            this.setFlag(QueryFlag.OUTPUT_TABLE);
        }
        return super.insert(data);
    }
    update(data) {
        if (this.mainAlias.meta?.hasTriggers) {
            this.setFlag(QueryFlag.OUTPUT_TABLE);
        }
        return super.update(data);
    }
    applyInsertDefaults(data) {
        if (!Array.isArray(data) || data.length < 2) {
            return data;
        }
        const meta = this.mainAlias.meta;
        const keys = Utils.unique(data.flatMap(row => Utils.keys(row))).filter(key => meta.properties[key]?.defaultRaw);
        if (keys.length === 0) {
            return data;
        }
        const schemaHelper = this.platform.getSchemaHelper();
        // MERGE uses a derived VALUES table, where DEFAULT is not allowed.
        return data.map(row => {
            let copy = row;
            for (const key of keys) {
                if (row[key] === undefined) {
                    if (copy === row) {
                        copy = { ...row };
                    }
                    const prop = meta.properties[key];
                    // same normalization as the DDL, e.g. `true` is not a valid MSSQL literal
                    copy[key] = raw(`${schemaHelper.normalizeDefaultValue(prop.defaultRaw, prop.length)}`);
                }
            }
            return copy;
        });
    }
    checkIdentityInsert(data) {
        const meta = this.mainAlias.meta;
        const dataKeys = Utils.unique(Utils.asArray(data).flatMap(d => Utils.keys(d)));
        const hasAutoincrement = dataKeys.some(x => {
            const prop = meta.properties[x];
            return prop?.autoincrement && (!meta.ownProps || meta.ownProps.includes(prop));
        });
        if (hasAutoincrement) {
            this.setFlag(QueryFlag.IDENTITY_INSERT);
        }
    }
}
